"""Conservative review gate for commands generated by the interpreter."""

import re
import shlex
import sys


READ_ONLY_COMMANDS = {
    "cat", "cut", "date", "df", "du", "echo", "egrep", "fgrep", "file",
    "getent", "grep", "groups", "head", "hostname", "id", "ls", "netstat",
    "nmap", "ping", "printenv", "printf", "ps", "pwd", "readlink", "sort",
    "ss", "stat", "tail", "tr", "true", "uname", "uniq", "uptime", "wc",
    "whoami",
}
CHANGING_COMMANDS = {
    "apt", "apt-get", "chmod", "chown", "chgrp", "cp", "dd", "docker",
    "fdisk", "kill", "killall", "mkfs", "mount", "mv", "parted", "passwd",
    "pkill", "reboot", "rm", "rmdir", "service", "setfacl", "shred",
    "shutdown", "systemctl", "tee", "truncate", "ufw", "umount", "useradd",
    "userdel", "usermod", "wipefs",
}


def review_reasons(command: str) -> list[str]:
    """Return reasons to ask for approval; an empty list means read-only syntax."""
    reasons = []
    try:
        tokens = shlex.split(command, posix=True)
    except ValueError:
        return ["The shell command could not be parsed safely"]
    if not tokens:
        return ["The command is empty"]

    words = [token.lower() for token in tokens]
    changing = sorted({word for word in words if word in CHANGING_COMMANDS})
    if changing:
        reasons.append("Changes or removes data/system state: " + ", ".join(changing))

    if re.search(r"(?<!<)>(?!>)|>>|>\||\b(?:eval|exec|sudo|su)\b", command):
        reasons.append("Contains output redirection or privileged/dynamic execution")
    if re.search(r"\$\(|`|(?:&&|\|\||[;|])", command):
        reasons.append("Contains compound shell syntax or command substitution")

    executable = words[0].rsplit("/", 1)[-1]
    if executable == "ip" and any(word in {"show", "get"} for word in words[1:]) and not any(
        word in {"add", "del", "delete", "set", "flush", "replace"} for word in words[1:]
    ):
        return reasons
    if executable not in READ_ONLY_COMMANDS and executable not in CHANGING_COMMANDS:
        reasons.append(f"'{executable}' is not verified as read-only")
    if executable == "nmap" and any(
        token == "-sc" or token.startswith("--script") or token.startswith(("-oa", "-og", "-on", "-ox", "-os"))
        for token in words[1:]
    ):
        reasons.append("Nmap scripts or output files may have side effects")

    return reasons


def approve_command(command: str, reasons: list[str], *, input_fn=input, is_tty=None) -> bool:
    """Request an explicit yes from a human at a terminal."""
    if not reasons:
        return True
    print("\n⚠️  Approval required before executing this remote command:")
    print(command)
    for reason in reasons:
        print(f"  • {reason}")
    if is_tty is None:
        is_tty = sys.stdin.isatty()
    if not is_tty:
        print("⛔ No interactive terminal is available; command not executed.")
        return False
    try:
        answer = input_fn("Type 'yes' to execute, or anything else to stop this goal: ")
    except (EOFError, KeyboardInterrupt):
        print("\n⛔ Command not approved.")
        return False
    return answer.strip().lower() == "yes"


def requests_human_confirmation(message: str) -> bool:
    """Detect a request to obtain human/owner approval before continuing."""
    if not message:
        return False
    text = " ".join(message.lower().split())
    actor = r"(?:system owner|owner|administrator|admin|human|user|operator)"
    approval = r"(?:confirm(?:ation)?|approv(?:e|al)|authoriz(?:e|ation)|permission|consent|review|verify|signs?[ -]?off)"
    request = r"(?:ask|have|obtain|get|request|require[sd]?|need[sd]?|must|await(?:ing)?|wait(?:ing)? for|please)"
    patterns = (
        rf"\b{request}\b.{{0,100}}\b{actor}\b.{{0,80}}\b{approval}\b",
        rf"\b{request}\b.{{0,100}}\b{approval}\b.{{0,80}}\b{actor}\b",
        rf"\b{actor}\b.{{0,80}}\b{request}\b.{{0,80}}\b{approval}\b",
        rf"\b{actor}\b.{{0,80}}\b{approval}\b.{{0,80}}\b{request}\b",
        rf"\b{approval}\b.{{0,80}}\b{actor}\b.{{0,80}}\b{request}\b",
    )
    return any(re.search(pattern, text) for pattern in patterns)


def request_human_confirmation(message: str, *, input_fn=input, is_tty=None) -> bool:
    """Ask the current user to approve an LLM or command-output request."""
    print("\n⚠️  Human confirmation requested:")
    print(message)
    if is_tty is None:
        is_tty = sys.stdin.isatty()
    if not is_tty:
        print("⛔ No interactive terminal is available; approval not given.")
        return False
    try:
        answer = input_fn("Type 'yes' if you approve, or anything else to stop this goal: ")
    except (EOFError, KeyboardInterrupt):
        print("\n⛔ Approval not given.")
        return False
    return answer.strip().lower() == "yes"


def confirmation_excerpt(message: str) -> str:
    """Show the relevant request without dumping a large command output."""
    for line in message.splitlines():
        if requests_human_confirmation(line):
            return line.strip()[:500]
    compact = " ".join(message.split())
    match = re.search(r"\b(?:system owner|owner|administrator|admin|human|user|operator)\b", compact, re.I)
    start = max(0, match.start() - 120) if match else 0
    return compact[start:start + 500]
